  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'X-Bridge-Secret': $env.BRIDGE_SECRET },
  body: JSON.stringify({ body })
})).json()).signature;
  const res = await fetch($env.YOBOT_BRIDGE_URL + '/api/bridge/send-message', { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + $env.BRIDGE_SECRET, 'X-Bridge-Signature': signature }, body: body });
  if (!res.ok) throw new Error('Bridge send-message: ' + res.status);
  return await res.json();
}
const res = await fetch('https://api.mercadolibre.com/messages/action_guide/packs/' + pack.packId + '/option?tag=post_sale', { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + account.access_token }, body: JSON.stringify({ option_id: 'OTHER', text: text }) });
if (!res.ok) throw new Error('ML action guide send: ' + res.status);
return await res.json();

